using System.Diagnostics;
using Microsoft.AspNetCore.Mvc;
using WebApplication1.Fingerprint;
using WebApplication1.Models;

namespace WebApplication1.Controllers;

public class HomeController : Controller
{
    private readonly ILogger<HomeController> _logger;
    private readonly FingerprintService _fingerprintService;

    public HomeController(ILogger<HomeController> logger, FingerprintService fingerprintService)
    {
        _logger = logger;
        _fingerprintService = fingerprintService;
    }

    public IActionResult Index()
    {
        bool isFingerprintInitialized = _fingerprintService.Initialize();
        ViewData["FingerprintStatus"] = isFingerprintInitialized ? "Fingerprint initialized successfully." : "Fingerprint initialization failed.";
        return View();
    }

    public IActionResult Privacy()
    {
        return View();
    }

    [HttpPost]
    public IActionResult TestCapture()
    {
        var template = _fingerprintService.CaptureFingerprintTemplate();
        if (template != null && template.Length > 0)
        {
            ViewData["CaptureResult"] = $"Fingerprint captured successfully. Template size: {template.Length} bytes.";
        }
        else
        {
            ViewData["CaptureResult"] = "Fingerprint capture failed.";
        }
        // Also show initialization status
        bool isFingerprintInitialized = _fingerprintService.Initialize();
        ViewData["FingerprintStatus"] = isFingerprintInitialized ? "Fingerprint initialized successfully." : "Fingerprint initialization failed.";
        return View("Index");
    }

    [ResponseCache(Duration = 0, Location = ResponseCacheLocation.None, NoStore = true)]
    public IActionResult Error()
    {
        return View(new ErrorViewModel { RequestId = Activity.Current?.Id ?? HttpContext.TraceIdentifier });
    }
}

using System.Diagnostics;
using Microsoft.AspNetCore.Mvc;
using WebApplication1.Fingerprint;
using WebApplication1.Models;

namespace WebApplication1.Controllers;

public class HomeController : Controller
{
    private readonly ILogger<HomeController> _logger;
    private readonly FingerprintService _fingerprintService;

    public HomeController(ILogger<HomeController> logger, FingerprintService fingerprintService)
    {
        _logger = logger;
        _fingerprintService = fingerprintService;
    }

    private void SetFingerprintDiagnostics()
    {
        ViewData["FingerprintStatus"] = _fingerprintService.IsInitialized ? "Initialized" : "Not initialized";
        ViewData["DeviceCount"] = _fingerprintService.DeviceCount;
        ViewData["ImageWidth"] = _fingerprintService.ImageWidth;
        ViewData["ImageHeight"] = _fingerprintService.ImageHeight;
        ViewData["LastError"] = _fingerprintService.LastError;
    }

    public IActionResult Index()
    {
        _fingerprintService.Initialize();
        SetFingerprintDiagnostics();
        return View();
    }

    public IActionResult Privacy()
    {
        return View();
    }

    [HttpPost]
    public async Task<IActionResult> TestCapture()
    {
        ViewData["Capturing"] = true;
        SetFingerprintDiagnostics();
        // Simulate waiting for animation (e.g., 3 seconds)
        await Task.Delay(3000);
        var template = _fingerprintService.CaptureFingerprintTemplate();
        ViewData["CaptureResult"] = (template != null && template.Length > 0)
            ? $"Fingerprint captured successfully. Template size: {template.Length} bytes."
            : "Fingerprint capture failed.";
        ViewData["Capturing"] = false;
        SetFingerprintDiagnostics();
        return View("Index");
    }

    [HttpPost]
    public IActionResult Reinitialize()
    {
        bool result = _fingerprintService.CloseAndReinitialize();
        ViewData["ReinitResult"] = result ? "Reinitialized successfully." : "Reinitialization failed.";
        SetFingerprintDiagnostics();
        return View("Index");
    }

    [HttpPost]
    public IActionResult CloseDevice()
    {
        bool result = _fingerprintService.CloseDeviceOnly();
        ViewData["CloseResult"] = result ? "Device closed successfully." : "Device was not open.";
        SetFingerprintDiagnostics();
        return View("Index");
    }

    [ResponseCache(Duration = 0, Location = ResponseCacheLocation.None, NoStore = true)]
    public IActionResult Error()
    {
        return View(new ErrorViewModel { RequestId = Activity.Current?.Id ?? HttpContext.TraceIdentifier });
    }
}

@{
    ViewData["Title"] = "Home Page";
}

<div class="text-center">
    <h1 class="display-4">Welcome</h1>
    <p>Learn about <a href="https://learn.microsoft.com/aspnet/core">building Web apps with ASP.NET Core</a>.</p>
    <p><strong>Fingerprint Status:</strong> @ViewData["FingerprintStatus"]</p>
    <form asp-action="TestCapture" method="post">
        <button type="submit" class="btn btn-primary">Test Capture</button>
    </form>
    @if (ViewData["CaptureResult"] != null)
    {
        <p><strong>Test Capture Result:</strong> @ViewData["CaptureResult"]</p>
    }
</div>

@{
    ViewData["Title"] = "Home Page";
    var isCapturing = ViewData["Capturing"] != null && (bool)ViewData["Capturing"];
}

<div class="text-center">
    <h1 class="display-4">Welcome</h1>
    <p>Learn about <a href="https://learn.microsoft.com/aspnet/core">building Web apps with ASP.NET Core</a>.</p>
    <p><strong>Fingerprint Status:</strong> @ViewData["FingerprintStatus"]</p>
    <p><strong>Device Count:</strong> @ViewData["DeviceCount"]</p>
    <p><strong>Image Width:</strong> @ViewData["ImageWidth"]</p>
    <p><strong>Image Height:</strong> @ViewData["ImageHeight"]</p>
    <p><strong>Last Error:</strong> @ViewData["LastError"]</p>
    <form asp-action="TestCapture" method="post" style="display:inline-block;margin-right:10px;">
        <button type="submit" class="btn btn-primary" @(isCapturing ? "disabled" : "")>Test Capture</button>
    </form>
    <form asp-action="Reinitialize" method="post" style="display:inline-block;margin-right:10px;">
        <button type="submit" class="btn btn-warning">Reinitialize Device</button>
    </form>
    <form asp-action="CloseDevice" method="post" style="display:inline-block;">
        <button type="submit" class="btn btn-danger">Close Device</button>
    </form>
    @if (isCapturing)
    {
        <div style="margin-top:20px;">
            <span class="spinner-border" role="status" aria-hidden="true"></span>
            <span>Capturing fingerprint, please wait...</span>
        </div>
    }
    @if (ViewData["CaptureResult"] != null)
    {
        <p><strong>Test Capture Result:</strong> @ViewData["CaptureResult"]</p>
    }
    @if (ViewData["ReinitResult"] != null)
    {
        <p><strong>Reinitialize Result:</strong> @ViewData["ReinitResult"]</p>
    }
    @if (ViewData["CloseResult"] != null)
    {
        <p><strong>Close Device Result:</strong> @ViewData["CloseResult"]</p>
    }
</div>
